   const line=(a,b)=>{c.beginPath();c.moveTo(...toCanvas(a));c.lineTo(...toCanvas(b));c.stroke();};
   const text=(label,point,align='center')=>{c.textAlign=align;c.fillText(label,...toCanvas(point));};
